import { readFileSync, writeFileSync, existsSync } from "fs";
import { join } from "path";
import { randomUUID } from "crypto";

// ============================================================================
// Sync History
// ============================================================================

const SYNC_HISTORY_FILE = ".orcha-sync-history.json";
const MAX_HISTORY_RUNS = 50;

export interface SyncHistorySignal {
  id: string;
  summary: string;
  source: string;
  status: string;
}

export interface SyncHistoryCandidate {
  id: string;
  title: string;
  category: string;
}

export interface SyncHistoryObligation {
  id: string;
  description: string;
  status: string;
  policyRef?: string;
}

export interface SyncHistoryRun {
  id: string;
  timestamp: string;
  commitHash: string;
  branch: string;
  completionStatus: string;
  signals: {
    total: number;
    bySource: Record<string, number>;
    items: SyncHistorySignal[];
  };
  candidates: {
    total: number;
    byCategory: Record<string, number>;
    items: SyncHistoryCandidate[];
  };
  obligations: {
    total: number;
    open: number;
    blocked: number;
    items: SyncHistoryObligation[];
  };
}

export interface SyncHistory {
  version: 1;
  runs: SyncHistoryRun[];
}

function syncHistoryPath(): string {
  return join(process.cwd(), SYNC_HISTORY_FILE);
}

export function readSyncHistory(): SyncHistory {
  const path = syncHistoryPath();
  if (!existsSync(path)) return { version: 1, runs: [] };
  try {
    return JSON.parse(readFileSync(path, "utf-8")) as SyncHistory;
  } catch {
    return { version: 1, runs: [] };
  }
}

export function appendSyncHistory(ledger: Ledger): void {
  const history = readSyncHistory();

  const bySource: Record<string, number> = {};
  for (const s of ledger.rawSignals) {
    bySource[s.source] = (bySource[s.source] ?? 0) + 1;
  }

  const byCategory: Record<string, number> = {};
  for (const c of ledger.candidates) {
    const cat = c.category ?? c.type ?? "unknown";
    byCategory[cat] = (byCategory[cat] ?? 0) + 1;
  }

  const obligationItems = ledger.obligations.map((o) => ({
    id: o.id,
    description: o.description ?? o.summary ?? "",
    status: o.status,
    policyRef: o.policyRef,
  }));

  const run: SyncHistoryRun = {
    id: randomUUID(),
    timestamp: new Date().toISOString(),
    commitHash: ledger.commitHash ?? "",
    branch: ledger.branch ?? "",
    completionStatus: ledger.completionStatus,
    signals: {
      total: ledger.rawSignals.length,
      bySource,
      items: ledger.rawSignals.map((s) => ({
        id: s.id,
        summary: s.summary,
        source: s.source,
        status: s.status,
      })),
    },
    candidates: {
      total: ledger.candidates.length,
      byCategory,
      items: ledger.candidates.map((c) => ({
        id: c.id,
        title: c.title ?? c.summary ?? "",
        category: c.category ?? c.type ?? "unknown",
      })),
    },
    obligations: {
      total: ledger.obligations.length,
      open: ledger.obligations.filter((o) => o.status === "open").length,
      blocked: ledger.obligations.filter((o) => o.status === "open" && o.priority === "critical").length,
      items: obligationItems,
    },
  };

  // Prepend newest, keep max
  history.runs = [run, ...history.runs].slice(0, MAX_HISTORY_RUNS);
  writeFileSync(syncHistoryPath(), JSON.stringify(history, null, 2), "utf-8");
}

// ============================================================================
// Core enums / union types
// ============================================================================

export type ObligationPriority = "critical" | "important" | "recommended";
export type ObligationStatus = "open" | "resolved" | "deferred" | "waived";
export type CompletionStatus = "complete" | "incomplete" | "blocked";

export type SignalSource = "conversation" | "manual" | "artifact_observation" | "code_observation";
export type SignalStatus = "new" | "classified" | "discarded";

export type CandidateType =
  | "decision" | "preference" | "constraint" | "tradeoff"
  | "assumption" | "finding" | "task" | "milestone_candidate"
  | "flow_change" | "feature_change"
  | "episodic" | "recommend_semantic" | "recommend_procedural";

export type CandidatePhase = "classified" | "normalized" | "reconciled";
export type CandidateAction = "persist_now" | "recommend_only" | "discard" | "unresolved";

export type TransitionNoteType = "defer_reason" | "waive_reason" | "conformance_hint" | "review_note";

export type SyncPhase = "raw" | "classified" | "normalized" | "obligations" | "complete";
export type SyncStatus = "draft" | "complete" | "incomplete" | "blocked";

// ============================================================================
// Data structures
// ============================================================================

export interface SessionMeta {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  topic?: string;
  policyVersion?: string;
  modelRefs?: string[];
}

export interface RawSignal {
  id: string;
  createdAt: string;
  source: SignalSource;
  summary: string;
  evidenceRefs?: string[];
  status: SignalStatus;
}

export interface Candidate {
  id: string;
  signalIds: string[];
  candidateType: CandidateType;
  summary: string;
  artifactRefs?: ArtifactRef[];
  classificationConfidence?: number;
  phase: CandidatePhase;
  action: CandidateAction;
}

export interface ArtifactRef {
  type: string;
  id: string;
}

export interface ObligationEntry {
  id: string;
  signalType: string;
  artifactId?: string;
  artifactTitle?: string;
  priority: ObligationPriority;
  description: string;
  rule?: string;
  status: ObligationStatus;
  detectedAt: string;
  resolvedAt?: string;
  deferralReason?: string;
  // v2 fields
  sourceSignalRefs: string[];
  relatedArtifactRefs: ArtifactRef[];
  reason?: string;
  deferReviewAt?: string;
}

export interface TransitionNote {
  id: string;
  createdAt: string;
  relatedCandidateId?: string;
  relatedObligationId?: string;
  noteType: TransitionNoteType;
  text: string;
}

export interface SyncRunState {
  currentPhase: SyncPhase;
  rawSignalIds: string[];
  candidateIds: string[];
  obligationIds: string[];
  syncStatus: SyncStatus;
}

export interface Ledger {
  version: 2;
  sessionMeta: SessionMeta;
  rawSignals: RawSignal[];
  candidates: Candidate[];
  obligations: ObligationEntry[];
  transitionNotes: TransitionNote[];
  syncRunState: SyncRunState;
  completionStatus: CompletionStatus;
  commitHash: string;
  branch: string;
  updatedAt: string;
}

// ============================================================================
// v1 legacy type (for migration)
// ============================================================================

interface LedgerV1 {
  version: 1;
  sessionId?: string;
  commitHash: string;
  branch: string;
  updatedAt: string;
  completionStatus: CompletionStatus;
  obligations: {
    id: string;
    signalType: string;
    artifactId?: string;
    artifactTitle?: string;
    priority: ObligationPriority;
    description: string;
    rule?: string;
    status: ObligationStatus;
    detectedAt: string;
    resolvedAt?: string;
    deferralReason?: string;
  }[];
}

// ============================================================================
// File operations
// ============================================================================

const LEDGER_FILE = ".orcha-ledger.json";

function ledgerPath(): string {
  return join(process.cwd(), LEDGER_FILE);
}

export function readLedger(): Ledger | null {
  const path = ledgerPath();
  if (!existsSync(path)) return null;
  try {
    const raw = JSON.parse(readFileSync(path, "utf-8"));
    if (raw.version === 1) return migrateV1(raw as LedgerV1);
    return raw as Ledger;
  } catch {
    return null;
  }
}

export function writeLedger(ledger: Ledger): void {
  writeFileSync(ledgerPath(), JSON.stringify(ledger, null, 2), "utf-8");
}

// ============================================================================
// Migration v1 → v2
// ============================================================================

function migrateV1(v1: LedgerV1): Ledger {
  const now = new Date().toISOString();
  return {
    version: 2,
    sessionMeta: {
      sessionId: v1.sessionId ?? randomUUID(),
      createdAt: v1.updatedAt,
      updatedAt: v1.updatedAt,
    },
    rawSignals: [],
    candidates: [],
    obligations: v1.obligations.map((o) => ({
      ...o,
      sourceSignalRefs: [],
      relatedArtifactRefs: o.artifactId
        ? [{ type: o.signalType, id: o.artifactId }]
        : [],
    })),
    transitionNotes: v1.obligations
      .filter((o) => o.status === "deferred" && o.deferralReason)
      .map((o) => ({
        id: randomUUID(),
        createdAt: now,
        relatedObligationId: o.id,
        noteType: "defer_reason" as TransitionNoteType,
        text: o.deferralReason!,
      })),
    syncRunState: {
      currentPhase: "complete",
      rawSignalIds: [],
      candidateIds: [],
      obligationIds: v1.obligations.map((o) => o.id),
      syncStatus: v1.completionStatus === "blocked" ? "blocked"
        : v1.completionStatus === "incomplete" ? "incomplete"
        : "complete",
    },
    completionStatus: v1.completionStatus,
    commitHash: v1.commitHash,
    branch: v1.branch,
    updatedAt: v1.updatedAt,
  };
}

// ============================================================================
// Factory: create empty ledger
// ============================================================================

export function createLedger(opts: {
  commitHash?: string;
  branch?: string;
  topic?: string;
}): Ledger {
  const now = new Date().toISOString();
  return {
    version: 2,
    sessionMeta: {
      sessionId: randomUUID(),
      createdAt: now,
      updatedAt: now,
      topic: opts.topic,
    },
    rawSignals: [],
    candidates: [],
    obligations: [],
    transitionNotes: [],
    syncRunState: {
      currentPhase: "raw",
      rawSignalIds: [],
      candidateIds: [],
      obligationIds: [],
      syncStatus: "draft",
    },
    completionStatus: "complete",
    commitHash: opts.commitHash ?? "",
    branch: opts.branch ?? "",
    updatedAt: now,
  };
}

// ============================================================================
// Add a RawSignal to the ledger
// ============================================================================

export function addSignal(
  ledger: Ledger,
  signal: Omit<RawSignal, "id" | "createdAt" | "status">
): RawSignal {
  const entry: RawSignal = {
    id: randomUUID(),
    createdAt: new Date().toISOString(),
    status: "new",
    ...signal,
  };
  ledger.rawSignals.push(entry);
  ledger.syncRunState.rawSignalIds.push(entry.id);
  ledger.sessionMeta.updatedAt = entry.createdAt;
  return entry;
}

// ============================================================================
// Add a TransitionNote to the ledger
// ============================================================================

export function addTransitionNote(
  ledger: Ledger,
  note: Omit<TransitionNote, "id" | "createdAt">
): TransitionNote {
  const entry: TransitionNote = {
    id: randomUUID(),
    createdAt: new Date().toISOString(),
    ...note,
  };
  ledger.transitionNotes.push(entry);
  return entry;
}

// ============================================================================
// Completion status derivation
// ============================================================================

export function deriveCompletionStatus(obligations: ObligationEntry[]): CompletionStatus {
  const open = obligations.filter((o) => o.status === "open");
  const criticalOpen = open.filter((o) => o.priority === "critical");
  const importantOpen = open.filter((o) => o.priority === "important");

  if (criticalOpen.length > 0) return "blocked";
  if (importantOpen.length > 0) return "incomplete";
  return "complete";
}

// ============================================================================
// Merge: preserve deferrals and resolutions from previous ledger
// ============================================================================

export function mergeWithPreviousLedger(
  newObligations: Omit<ObligationEntry, "status" | "detectedAt" | "resolvedAt" | "deferralReason" | "deferReviewAt">[],
  previous: Ledger | null
): ObligationEntry[] {
  const now = new Date().toISOString();

  return newObligations.map((o) => {
    const prev = previous?.obligations.find(
      (p) => p.rule === o.rule && p.artifactId === o.artifactId
    );

    if (prev && (prev.status === "deferred" || prev.status === "waived" || prev.status === "resolved")) {
      return {
        ...o,
        status: prev.status,
        detectedAt: prev.detectedAt,
        resolvedAt: prev.resolvedAt,
        deferralReason: prev.deferralReason,
        deferReviewAt: prev.deferReviewAt,
      };
    }

    return {
      ...o,
      status: "open" as ObligationStatus,
      detectedAt: now,
    };
  });
}

