import { db } from "@/db";
import { syncLogs } from "@/db/schema";
import { requireAuth } from "@/lib/api/auth";
import { ok, created, handleError } from "@/lib/api/response";
import { eq, desc } from "drizzle-orm";

type Params = { params: Promise<{ id: string }> };

export async function GET(_request: Request, { params }: Params) {
  try {
    await requireAuth();
    const { id } = await params;

    const logs = await db.query.syncLogs.findMany({
      where: eq(syncLogs.projectId, id),
      orderBy: [desc(syncLogs.createdAt)],
      limit: 20,
    });

    return ok(logs);
  } catch (err) {
    return handleError(err);
  }
}

export async function POST(request: Request, { params }: Params) {
  try {
    await requireAuth();
    const { id } = await params;
    const body = await request.json();

    const [log] = await db
      .insert(syncLogs)
      .values({
        projectId: id,
        commitHash: body.commitHash,
        branch: body.branch,
        updates: body.updates,
        createdBy: body.createdBy ?? "orcha-cli",
      })
      .returning();

    return created(log);
  } catch (err) {
    return handleError(err);
  }
}

import { db } from "@/db";
import { projects } from "@/db/schema";
import { eq } from "drizzle-orm";
import { notFound } from "next/navigation";

import { AppSidebar } from "@/components/app-sidebar";
import { ProjectHealth } from "@/components/project-health";

type Params = { params: Promise<{ id: string }> };

export default async function StatusPage({ params }: Params) {
  const { id } = await params;

  const project = await db.query.projects.findFirst({
    where: eq(projects.id, id),
    columns: { id: true, name: true },
  });

  if (!project) notFound();

  return (
    <div className="min-h-screen flex flex-col">
      <div className="flex flex-1">
        <AppSidebar projectId={project.id} projectName={project.name} />
        <main className="flex-1 min-w-0 p-6 overflow-y-auto">
          <div className="max-w-4xl mx-auto">
            <ProjectHealth projectId={project.id} />
          </div>
        </main>
      </div>
    </div>
  );
}

