import { useActiveWorkspace } from "@/context/AppShellContext"
import { routes, navigate } from "@/lib/navigate"
import type { LedgerActivityEvent, LedgerSignalDelta } from "../../../shared/ledger-activity"

// ─── Types ───────────────────────────────────────────────────────────────────

interface LedgerEvent {
  id: string
  timestamp: string
  type: "signal" | "sync" | "obligation"
  source?: string
  summary: string
  signalsDelta?: LedgerSignalDelta[]
  completionStatus?: string
  syncPhase?: string
}

// ─── Helpers ─────────────────────────────────────────────────────────────────

function relativeTime(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime()
  const secs = Math.floor(diff / 1000)
  if (secs < 60) return `${secs}s`
  const mins = Math.floor(secs / 60)
  if (mins < 60) return `${mins}m`
  const hours = Math.floor(mins / 60)
  return `${hours}h`
}

function signalIcon(source: string) {
  switch (source) {
    case "conversation":
    case "manual":
      return MessageSquare
    case "code_observation":
      return GitCommit
    case "artifact_observation":
      return FileSearch
    default:
      return MessageSquare
  }
}

function signalIconColor(source: string): string {
  switch (source) {
    case "conversation":
    case "manual":
      return "color-mix(in oklch, var(--accent) 80%, transparent)"
    case "code_observation":
      return "color-mix(in oklch, var(--foreground) 50%, transparent)"
    case "artifact_observation":
      return "color-mix(in oklch, var(--info) 80%, transparent)"
    default:
      return "color-mix(in oklch, var(--foreground) 50%, transparent)"
  }
}

function obligationColor(status: string): string {
  switch (status) {
    case "blocked":
      return "color-mix(in oklch, var(--destructive) 90%, transparent)"
    case "incomplete":
      return "color-mix(in oklch, var(--info) 90%, transparent)"
    case "complete":
      return "color-mix(in oklch, var(--success) 80%, transparent)"
    default:
      return "color-mix(in oklch, var(--foreground) 40%, transparent)"
  }
}

function activityToEvents(event: LedgerActivityEvent): LedgerEvent[] {
  const events: LedgerEvent[] = []

  // New signals → individual event rows
  if (event.signalsDelta && event.signalsDelta.length > 0) {
    for (const s of event.signalsDelta) {
      events.push({
        id: s.id,
        timestamp: event.timestamp,
        type: "signal",
        source: s.source,
        summary: s.summary || "Signal",
        signalsDelta: [s],
      })
    }
  } else {
    // Always show sync state — even when ledger is clean (0 candidates/obligations)
    events.push({
      id: `sync-${event.timestamp}`,
      timestamp: event.timestamp,
      type: "sync",
      summary: `Sync · ${event.syncPhase}`,
      completionStatus: event.completionStatus,
      syncPhase: event.syncPhase,
    })
  }

  // Obligation alert if blocked/incomplete
  if (event.obligations > 0 && (event.completionStatus === "blocked" || event.completionStatus === "incomplete")) {
    events.push({
      id: `obl-${event.timestamp}`,
      timestamp: event.timestamp,
      type: "obligation",
      summary: `${event.obligations} Obligation${event.obligations > 1 ? "s" : ""} offen`,
      completionStatus: event.completionStatus,
    })
  }

  return events
}

// ─── LedgerPanel ─────────────────────────────────────────────────────────────

const MAX_EVENTS = 5
const AUTO_COLLAPSE_MS = 30_000

export function LedgerPanel() {
  const focusedSessionId = useAtomValue(focusedSessionIdAtom)
  const sessionMetaMap = useAtomValue(sessionMetaMapAtom)
  const activeWorkspace = useActiveWorkspace()
  const setLedgerWorkingDir = useSetAtom(ledgerWorkingDirAtom)

  const sessionWorkingDir = focusedSessionId
    ? sessionMetaMap.get(focusedSessionId)?.workingDirectory ?? null
    : null
  const workingDirectory = sessionWorkingDir || null

  const [events, setEvents] = React.useState<LedgerEvent[]>([])
  const [totals, setTotals] = React.useState({ signals: 0, candidates: 0, obligations: 0 })
  const [isExpanded, setIsExpanded] = React.useState(true)
  const [hasNew, setHasNew] = React.useState(false)
  const [newCount, setNewCount] = React.useState(0)
  const autoCollapseTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null)

  // Reset state when working directory changes
  React.useEffect(() => {
    setEvents([])
    setTotals({ signals: 0, candidates: 0, obligations: 0 })
    setHasNew(false)
    setNewCount(0)
    setIsExpanded(true)
  }, [workingDirectory])

  // Start/stop ledger watcher when working directory changes
  React.useEffect(() => {
    if (!workingDirectory || !window.electronAPI?.ledgerWatch) return

    window.electronAPI.ledgerWatch(workingDirectory).catch(() => {})

    const unsubscribe = window.electronAPI.onLedgerActivity?.((event: LedgerActivityEvent) => {
      setTotals({
        signals: event.signals,
        candidates: event.candidates,
        obligations: event.obligations,
      })

      const newEvents = activityToEvents(event)
      if (newEvents.length === 0) return

      setEvents((prev) => [...newEvents, ...prev].slice(0, MAX_EVENTS))
      setHasNew(true)
      setNewCount((n) => n + newEvents.length)

      // Auto-expand on new activity
      setIsExpanded(true)

      // Auto-collapse after inactivity
      if (autoCollapseTimer.current) clearTimeout(autoCollapseTimer.current)
      autoCollapseTimer.current = setTimeout(() => {
        setIsExpanded(false)
      }, AUTO_COLLAPSE_MS)
    })

    return () => {
      unsubscribe?.()
      window.electronAPI?.ledgerUnwatch?.().catch(() => {})
      if (autoCollapseTimer.current) clearTimeout(autoCollapseTimer.current)
    }
  }, [workingDirectory])

  // Clear "new" badge when user expands
  const handleToggle = () => {
    const next = !isExpanded
    setIsExpanded(next)
    if (next) {
      setHasNew(false)
      setNewCount(0)
    }
    if (!next && autoCollapseTimer.current) {
      clearTimeout(autoCollapseTimer.current)
    }
  }

  const hasEvents = events.length > 0
  const hasSummary = totals.signals > 0 || totals.candidates > 0 || totals.obligations > 0

  return (
    <div className="mx-2 mb-2 rounded-[6px] border border-foreground/[0.06] bg-foreground/[0.02]">
      {/* ── Header ─────────────────────────────────────────────────────── */}
      <button
        onClick={handleToggle}
        className={cn(
          "group/header w-full flex items-center gap-2 rounded-[6px] py-[5px] px-2 select-none",
          "hover:bg-foreground/[0.04] transition-colors duration-150 text-left",
        )}
      >
        <BookOpen
          className="h-3.5 w-3.5 shrink-0"
          style={{ color: "color-mix(in oklch, var(--foreground) 60%, transparent)" }}
        />
        <span className="text-[13px] font-medium text-foreground/60 flex-1">Ledger</span>

        {/* New-activity pulse dot */}
        <AnimatePresence>
          {hasNew && (
            <motion.span
              key="pulse"
              initial={{ opacity: 0, scale: 0.5 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.5 }}
              transition={{ duration: 0.2 }}
              className="relative flex h-2 w-2 shrink-0"
            >
              <span
                className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-60"
                style={{ backgroundColor: "var(--accent)" }}
              />
              <span
                className="relative inline-flex rounded-full h-2 w-2"
                style={{ backgroundColor: "var(--accent)" }}
              />
            </motion.span>
          )}
        </AnimatePresence>

        {/* New count badge (collapsed only) */}
        {!isExpanded && newCount > 0 && (
          <span
            className="text-xs shrink-0"
            style={{ color: "var(--accent)" }}
          >
            {newCount} neu
          </span>
        )}

        {/* Chevron */}
        <ChevronRight
          className={cn(
            "h-3.5 w-3.5 shrink-0 transition-transform duration-200 text-foreground/30",
            isExpanded && "rotate-90"
          )}
        />
      </button>

      {/* ── Body ───────────────────────────────────────────────────────── */}
      <AnimatePresence initial={false}>
        {isExpanded && (
          <motion.div
            key="body"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.2, ease: "easeInOut" }}
            className="overflow-hidden"
          >
            {!workingDirectory ? (
              <div className="py-2 px-2">
                <span className="text-xs text-foreground/25">Kein Arbeitsverzeichnis</span>
              </div>
            ) : hasEvents ? (
              <div className="pb-1">
                {events.map((event) => (
                  <EventRow key={event.id} event={event} />
                ))}
              </div>
            ) : (
              <div className="py-2 px-2">
                <span className="text-xs text-foreground/25">Warte auf Aktivität…</span>
              </div>
            )}

            {/* Summary footer — always visible when working directory is set */}
            {workingDirectory && (
              <div className="flex items-center gap-2 border-t border-foreground/[0.04] py-1.5 px-2">
                {hasSummary && (
                  <span className="text-xs text-foreground/30">
                    {totals.signals} Sig
                    {totals.candidates > 0 && ` · ${totals.candidates} Kand`}
                    {totals.obligations > 0 && ` · ${totals.obligations} Obl`}
                  </span>
                )}
                <button
                  onClick={(e) => { e.stopPropagation(); setLedgerWorkingDir(workingDirectory); navigate(routes.view.ledger()) }}
                  className="ml-auto flex items-center gap-1 text-[11px] text-foreground/30 hover:text-foreground/60 transition-colors"
                >
                  Details
                  <ExternalLink className="h-2.5 w-2.5" />
                </button>
              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

// ─── EventRow ────────────────────────────────────────────────────────────────

function EventRow({ event }: { event: LedgerEvent }) {
  let Icon: React.ComponentType<{ className?: string; style?: React.CSSProperties }>
  let iconColor: string
  let label: string

  switch (event.type) {
    case "signal": {
      const src = event.source ?? ""
      Icon = signalIcon(src)
      iconColor = signalIconColor(src)
      label = event.summary.length > 36 ? event.summary.slice(0, 36) + "…" : event.summary
      break
    }
    case "sync":
      Icon = RefreshCw
      iconColor = "color-mix(in oklch, var(--success) 80%, transparent)"
      label = event.summary
      break
    case "obligation":
      Icon = AlertTriangle
      iconColor = obligationColor(event.completionStatus ?? "")
      label = event.summary
      break
    default:
      Icon = BookOpen
      iconColor = "color-mix(in oklch, var(--foreground) 40%, transparent)"
      label = event.summary
  }

  return (
    <div className="flex items-center gap-2 py-[3px] px-2">
      <Icon className="h-3 w-3 shrink-0" style={{ color: iconColor }} />
      <span className="text-[12px] text-foreground/55 flex-1 truncate">{label}</span>
      <span className="text-[11px] text-foreground/25 shrink-0">
        {relativeTime(event.timestamp)}
      </span>
    </div>
  )
}

/**
 * LedgerDetailPage
 *
 * Full-page view of the Orcha Ledger showing all signals, candidates, and obligations.
 * Accessible via the LedgerPanel sidebar or the `ledger` route.
 */

import * as React from 'react'
import {
  BookOpen,
  MessageSquare,
  GitCommit,
  FileSearch,
  RefreshCw,
  AlertTriangle,
  CheckCircle2,
  Clock,
  XCircle,
  ChevronDown,
  ChevronRight,
  History,
} from 'lucide-react'
import { cn } from '@/lib/utils'
import { useAtomValue } from 'jotai'
import { ledgerWorkingDirAtom } from '@/atoms/panel-stack'
import {
  Info_Page,
  Info_Section,
} from '@/components/info'
import type { LedgerData, LedgerSignal, LedgerCandidate, LedgerObligation, SyncHistory, SyncHistoryRun } from '../../shared/ledger-activity'

// ─── Helpers ─────────────────────────────────────────────────────────────────

function formatDate(iso: string): string {
  if (!iso) return '—'
  const d = new Date(iso)
  return d.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' })
    + ', ' + d.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' })
}

function sourceIcon(source: string) {
  switch (source) {
    case 'conversation':
    case 'manual':
      return MessageSquare
    case 'code_observation':
      return GitCommit
    case 'artifact_observation':
      return FileSearch
    default:
      return MessageSquare
  }
}

function sourceLabel(source: string): string {
  switch (source) {
    case 'conversation': return 'Conversation'
    case 'manual': return 'Manuell'
    case 'code_observation': return 'Code'
    case 'artifact_observation': return 'Artefakt'
    default: return source
  }
}

function sourceColor(source: string): string {
  switch (source) {
    case 'conversation':
    case 'manual':
      return 'color-mix(in oklch, var(--accent) 80%, transparent)'
    case 'code_observation':
      return 'color-mix(in oklch, var(--foreground) 50%, transparent)'
    case 'artifact_observation':
      return 'color-mix(in oklch, var(--info) 80%, transparent)'
    default:
      return 'color-mix(in oklch, var(--foreground) 50%, transparent)'
  }
}

function obligationStatusIcon(status: string) {
  switch (status) {
    case 'complete': return CheckCircle2
    case 'open': return Clock
    case 'blocked': return XCircle
    default: return AlertTriangle
  }
}

function obligationStatusColor(status: string): string {
  switch (status) {
    case 'complete': return 'color-mix(in oklch, var(--success) 80%, transparent)'
    case 'open': return 'color-mix(in oklch, var(--info) 80%, transparent)'
    case 'blocked': return 'color-mix(in oklch, var(--destructive) 80%, transparent)'
    default: return 'color-mix(in oklch, var(--foreground) 40%, transparent)'
  }
}

type Tab = 'signals' | 'candidates' | 'obligations' | 'history'

// ─── LedgerDetailPage ────────────────────────────────────────────────────────

export default function LedgerDetailPage() {
  const workingDirectory = useAtomValue(ledgerWorkingDirAtom)

  const [data, setData] = React.useState<LedgerData | null>(null)
  const [history, setHistory] = React.useState<SyncHistory>({ version: 1, runs: [] })
  const [loading, setLoading] = React.useState(true)
  const [error, setError] = React.useState<string | null>(null)
  const [activeTab, setActiveTab] = React.useState<Tab>('history')

  const loadData = React.useCallback(async () => {
    if (!workingDirectory) {
      setError('Kein Arbeitsverzeichnis — öffne eine Session mit Orcha-Projekt.')
      setLoading(false)
      return
    }

    setLoading(true)
    setError(null)
    console.log('[Ledger] loadData — workingDirectory:', workingDirectory)
    try {
      const hasHistoryApi = typeof window.electronAPI?.ledgerHistory === 'function'
      console.log('[Ledger] hasHistoryApi:', hasHistoryApi)
      const [result, hist] = await Promise.all([
        window.electronAPI.ledgerRead(workingDirectory),
        hasHistoryApi
          ? window.electronAPI.ledgerHistory(workingDirectory)
          : Promise.resolve({ version: 1 as const, runs: [] }),
      ])
      console.log('[Ledger] ledgerRead result:', result ? `${result.signals.length}S ${result.candidates.length}C ${result.obligations.length}O` : 'null')
      console.log('[Ledger] ledgerHistory result:', hist ? `${hist.runs.length} runs` : 'null/undefined')
      if (hist?.runs?.length > 0) {
        console.log('[Ledger] First run:', hist.runs[0].timestamp, hist.runs[0].commitHash, `${hist.runs[0].signals.total}S`)
      }
      setData(result ?? null)
      setHistory(hist)
      if (!hasHistoryApi) {
        console.warn('[Ledger] ledgerHistory API nicht verfügbar — Preload neu bauen?')
      }
    } catch (err) {
      console.error('[Ledger] loadData error:', err)
      setError('Fehler beim Laden des Ledger.')
    } finally {
      setLoading(false)
    }
  }, [workingDirectory])

  React.useEffect(() => { loadData() }, [loadData])

  return (
    <Info_Page loading={loading} error={error ?? undefined}>
      <Info_Page.Header
        title="Ledger"
        badge={<BookOpen className="h-4 w-4 text-foreground/40" />}
        actions={
          <button
            onClick={loadData}
            className="flex items-center gap-1.5 px-2 py-1 rounded-md text-xs text-foreground/50 hover:text-foreground/80 hover:bg-foreground/[0.06] transition-colors"
          >
            <RefreshCw className="h-3 w-3" />
            Aktualisieren
          </button>
        }
      />
      <Info_Page.Content>
        <>
          {/* Summary bar — only when ledger is loaded */}
          {data && (
            <div className="flex items-center gap-3 px-4 py-2 border-b border-foreground/[0.06]">
              <span className="text-xs text-foreground/40">
                Status: <span className="text-foreground/60 font-medium">{data.completionStatus}</span>
              </span>
              <span className="text-xs text-foreground/40">
                Sync: <span className="text-foreground/60 font-medium">{data.syncStatus}</span>
              </span>
              {data.updatedAt && (
                <span className="text-xs text-foreground/30 ml-auto">
                  Aktualisiert: {formatDate(data.updatedAt)}
                </span>
              )}
            </div>
          )}

          {/* Tabs */}
          <div className="flex border-b border-foreground/[0.06]">
            <TabButton
              active={activeTab === 'history'}
              onClick={() => setActiveTab('history')}
              label={`Sync History (${history.runs.length})`}
            />
            {data && (
              <>
                <TabButton
                  active={activeTab === 'signals'}
                  onClick={() => setActiveTab('signals')}
                  label={`Signale (${data.signals.length})`}
                />
                <TabButton
                  active={activeTab === 'candidates'}
                  onClick={() => setActiveTab('candidates')}
                  label={`Candidates (${data.candidates.length})`}
                />
                <TabButton
                  active={activeTab === 'obligations'}
                  onClick={() => setActiveTab('obligations')}
                  label={`Obligations (${data.obligations.length})`}
                />
              </>
            )}
          </div>

          {/* Tab content */}
          <div className="flex-1 overflow-y-auto">
            {activeTab === 'history' && <HistoryTab runs={history.runs} />}
            {data && activeTab === 'signals' && <SignalsTab signals={data.signals} />}
            {data && activeTab === 'candidates' && <CandidatesTab candidates={data.candidates} signals={data.signals} />}
            {data && activeTab === 'obligations' && <ObligationsTab obligations={data.obligations} />}
          </div>
        </>
      </Info_Page.Content>
    </Info_Page>
  )
}

// ─── Tab Button ──────────────────────────────────────────────────────────────

function TabButton({ active, onClick, label }: { active: boolean; onClick: () => void; label: string }) {
  return (
    <button
      onClick={onClick}
      className={cn(
        'px-4 py-2 text-xs font-medium transition-colors border-b-2 -mb-px',
        active
          ? 'text-foreground/80 border-accent'
          : 'text-foreground/40 border-transparent hover:text-foreground/60 hover:border-foreground/10'
      )}
    >
      {label}
    </button>
  )
}

// ─── Signals Tab ─────────────────────────────────────────────────────────────

function SignalsTab({ signals }: { signals: LedgerSignal[] }) {
  // Group by source
  const grouped = React.useMemo(() => {
    const groups = new Map<string, LedgerSignal[]>()
    for (const s of signals) {
      const list = groups.get(s.source) || []
      list.push(s)
      groups.set(s.source, list)
    }
    // Sort each group by createdAt desc
    for (const list of groups.values()) {
      list.sort((a, b) => b.createdAt.localeCompare(a.createdAt))
    }
    return groups
  }, [signals])

  // Source order: conversation first, then others
  const orderedSources = React.useMemo(() => {
    const sources = Array.from(grouped.keys())
    sources.sort((a, b) => {
      if (a === 'conversation') return -1
      if (b === 'conversation') return 1
      return a.localeCompare(b)
    })
    return sources
  }, [grouped])

  if (signals.length === 0) {
    return <EmptyState text="Keine Signale im Ledger." />
  }

  return (
    <div className="py-2">
      {orderedSources.map(source => {
        const items = grouped.get(source) || []
        const Icon = sourceIcon(source)
        return (
          <Info_Section key={source} title={sourceLabel(source)} actions={<span className="text-xs text-foreground/40 bg-foreground/[0.06] px-1.5 py-0.5 rounded-full">{items.length}</span>}>
            <div className="space-y-0.5">
              {items.map(signal => (
                <div key={signal.id} className="flex items-start gap-2.5 py-1.5 px-3 rounded-md hover:bg-foreground/[0.03]">
                  <Icon className="h-3.5 w-3.5 mt-0.5 shrink-0" style={{ color: sourceColor(source) }} />
                  <div className="flex-1 min-w-0">
                    <span className="text-[13px] text-foreground/70 leading-snug block">
                      {signal.summary}
                    </span>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-[11px] text-foreground/30">{formatDate(signal.createdAt)}</span>
                      <span className={cn(
                        'text-[10px] px-1.5 py-0.5 rounded-full',
                        signal.status === 'classified'
                          ? 'bg-foreground/[0.06] text-foreground/40'
                          : 'bg-accent/10 text-accent'
                      )}>
                        {signal.status}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </Info_Section>
        )
      })}
    </div>
  )
}

// ─── Candidates Tab ──────────────────────────────────────────────────────────

function CandidatesTab({ candidates, signals }: { candidates: LedgerCandidate[]; signals: LedgerSignal[] }) {
  const signalMap = React.useMemo(() => {
    const map = new Map<string, LedgerSignal>()
    for (const s of signals) map.set(s.id, s)
    return map
  }, [signals])

  if (candidates.length === 0) {
    return <EmptyState text="Keine Candidates im Ledger." />
  }

  return (
    <div className="py-2">
      <Info_Section title="Episodic Memory Candidates" actions={<span className="text-xs text-foreground/40 bg-foreground/[0.06] px-1.5 py-0.5 rounded-full">{candidates.length}</span>}>
        <div className="space-y-1">
          {candidates.map(c => (
            <div key={c.id} className="py-2 px-3 rounded-md hover:bg-foreground/[0.03]">
              <div className="flex items-center gap-2">
                <span className="text-[13px] text-foreground/70 font-medium">{c.title}</span>
                <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-foreground/[0.06] text-foreground/40">
                  {c.category}
                </span>
              </div>
              {c.signalIds.length > 0 && (
                <div className="mt-1 flex flex-wrap gap-1">
                  {c.signalIds.map(sid => {
                    const signal = signalMap.get(sid)
                    return (
                      <span key={sid} className="text-[11px] text-foreground/30 truncate max-w-[200px]" title={signal?.summary}>
                        ← {signal ? signal.summary.slice(0, 40) : sid.slice(0, 8)}
                      </span>
                    )
                  })}
                </div>
              )}
              {c.createdAt && (
                <span className="text-[11px] text-foreground/25 mt-0.5 block">{formatDate(c.createdAt)}</span>
              )}
            </div>
          ))}
        </div>
      </Info_Section>
    </div>
  )
}

// ─── Obligations Tab ─────────────────────────────────────────────────────────

function ObligationsTab({ obligations }: { obligations: LedgerObligation[] }) {
  if (obligations.length === 0) {
    return <EmptyState text="Keine Obligations im Ledger." />
  }

  return (
    <div className="py-2">
      <Info_Section title="Obligations" actions={<span className="text-xs text-foreground/40 bg-foreground/[0.06] px-1.5 py-0.5 rounded-full">{obligations.length}</span>}>
        <div className="space-y-1">
          {obligations.map(o => {
            const Icon = obligationStatusIcon(o.status)
            return (
              <div key={o.id} className="flex items-start gap-2.5 py-1.5 px-3 rounded-md hover:bg-foreground/[0.03]">
                <Icon className="h-3.5 w-3.5 mt-0.5 shrink-0" style={{ color: obligationStatusColor(o.status) }} />
                <div className="flex-1 min-w-0">
                  <span className="text-[13px] text-foreground/70">{o.description || o.id}</span>
                  <div className="flex items-center gap-2 mt-0.5">
                    <span className={cn(
                      'text-[10px] px-1.5 py-0.5 rounded-full',
                      o.status === 'complete'
                        ? 'bg-green-500/10 text-green-500'
                        : o.status === 'blocked'
                          ? 'bg-red-500/10 text-red-500'
                          : 'bg-blue-500/10 text-blue-500'
                    )}>
                      {o.status}
                    </span>
                    {o.policyRef && (
                      <span className="text-[11px] text-foreground/30">→ {o.policyRef}</span>
                    )}
                  </div>
                </div>
              </div>
            )
          })}
        </div>
      </Info_Section>
    </div>
  )
}

