  /** Total rawSignals in ledger */
  signals: number
  /** New signals added since last check */
  signalsDelta: LedgerSignalDelta[]
  /** Total candidates */
  candidates: number
  /** Open obligations count */
  obligations: number
  /** 'complete' | 'incomplete' | 'blocked' | 'unknown' */
