import { execSync } from "child_process";
import type { SyncContext } from "./sync-context.js";
import {
  type Ledger,
  type RawSignal,
  addSignal,
} from "./ledger.js";

// ============================================================================
// Collect all signals from the three sources
// ============================================================================

export interface SignalCollectionResult {
  fromLedger: RawSignal[];
  fromArtifacts: RawSignal[];
  fromCode: RawSignal[];
  all: RawSignal[];
}

/**
 * Collect RawSignals from all three sources into the ledger.
 * Returns the collected signals grouped by source.
 */
export function collectSignals(
  ledger: Ledger,
  ctx: SyncContext,
  since: Date
): SignalCollectionResult {
  // 1. Existing ledger signals (conversation + manual) — already present
  const fromLedger = ledger.rawSignals.filter(
    (s) => s.status === "new" && (s.source === "conversation" || s.source === "manual")
  );

  // 2. Artifact observations from pre-fetched context
  const fromArtifacts = collectArtifactSignals(ledger, ctx, since);

  // 3. Code observations from git diff
  const fromCode = collectCodeSignals(ledger, since);

  return {
    fromLedger,
    fromArtifacts,
    fromCode,
    all: [...fromLedger, ...fromArtifacts, ...fromCode],
  };
}

// ============================================================================
// Signal deduplication
// ============================================================================

/**
 * Checks if a signal with the same source and primary evidence ref
 * already exists in the ledger (not discarded).
 */
function signalExists(ledger: Ledger, source: string, evidenceRef: string): boolean {
  return ledger.rawSignals.some(
    (s) => s.source === source &&
           s.status !== "discarded" &&
           s.evidenceRefs?.includes(evidenceRef)
  );
}

// ============================================================================
// Artifact observation signals (from SyncContext)
// ============================================================================

function collectArtifactSignals(
  ledger: Ledger,
  ctx: SyncContext,
  since: Date
): RawSignal[] {
  const signals: RawSignal[] = [];

  // --- Decisions ---
  for (const d of ctx.decisions) {
    const created = d.createdAt ?? d.created_at;
    const updated = d.updatedAt ?? d.updated_at;
    const isNew = created && new Date(created) > since;
    const isChanged = updated && new Date(updated) > since && !isNew;

    if (isNew) {
      const ref = `decision:${d.id}`;
      if (signalExists(ledger, "artifact_observation", ref)) continue;

      const durability = d.durability ?? "unbekannt";
      const tradeOff = d.tradeOffId ?? d.trade_off_id;
      const modelRefs = d.modelRefs ?? d.model_refs ?? [];
      const details = [
        `durability=${durability}`,
        tradeOff ? `trade-off=${tradeOff}` : "kein Trade-off",
        modelRefs.length > 0 ? `model-refs=${modelRefs.length}` : "keine Modell-Referenz",
      ].join(", ");

      signals.push(addSignal(ledger, {
        source: "artifact_observation",
        summary: `Neue Entscheidung: „${d.title}" (${details})`,
        evidenceRefs: [ref],
      }));
    } else if (isChanged) {
      const ref = `decision:${d.id}`;
      if (signalExists(ledger, "artifact_observation", ref)) continue;

      signals.push(addSignal(ledger, {
        source: "artifact_observation",
        summary: `Geänderte Entscheidung: „${d.title}"`,
        evidenceRefs: [ref],
      }));
    }
  }

  // --- Preferences (only active) ---
  const activePrefs = ctx.preferences.filter((p: any) => p.status === "active");
  for (const p of activePrefs) {
    const ref = `preference:${p.id}`;
    if (signalExists(ledger, "artifact_observation", ref)) continue;

    signals.push(addSignal(ledger, {
      source: "artifact_observation",
      summary: `Aktive Präferenz: „${p.title}" (${p.source ?? "unbekannt"})`,
      evidenceRefs: [ref],
    }));
  }

  // --- Tasks without feature reference ---
  const orphanTasks = ctx.tasks.filter((t: any) => !(t.featureId ?? t.feature_id));
  for (const t of orphanTasks) {
    const ref = `task:${t.id}`;
    if (signalExists(ledger, "artifact_observation", ref)) continue;

    signals.push(addSignal(ledger, {
      source: "artifact_observation",
      summary: `Entwicklungsaufgabe ohne Feature-Referenz: „${t.title}"`,
      evidenceRefs: [ref],
    }));
  }

  // --- Milestones without feature bundling ---
  for (const m of ctx.milestones) {
    const linkedFeatures = m.milestoneFeatures ?? m.milestone_features ?? [];
    if (linkedFeatures.length === 0 && m.status !== "completed" && m.status !== "cancelled") {
      const ref = `milestone:${m.id}`;
      if (signalExists(ledger, "artifact_observation", ref)) continue;

      signals.push(addSignal(ledger, {
        source: "artifact_observation",
        summary: `Meilenstein ohne Feature-Bündelung: „${m.name}"`,
        evidenceRefs: [ref],
      }));
    }
  }

  return signals;
}

// ============================================================================
// Code observation signals (from git diff)
// ============================================================================

function collectCodeSignals(
  ledger: Ledger,
  _since: Date
): RawSignal[] {
  const signals: RawSignal[] = [];

  try {
    const diffOutput = execSync(
      "git diff --cached --name-only 2>/dev/null || git diff --name-only HEAD",
      { encoding: "utf-8" }
    ).trim();

    if (!diffOutput) return signals;

    const files = diffOutput.split("\n").filter(Boolean);

    // Model/policy changes
    const modelFiles = files.filter((f) =>
      f.includes("docs/konzept") || f.includes("orcha-model")
    );
    for (const f of modelFiles) {
      const ref = `file:${f}`;
      if (signalExists(ledger, "code_observation", ref)) continue;

      signals.push(addSignal(ledger, {
        source: "code_observation",
        summary: `Modell-/Policy-Datei geändert: ${f}`,
        evidenceRefs: [ref],
      }));
    }

    // Flow/intent changes
    const flowFiles = files.filter((f) =>
      f.includes("userflow") || f.includes("absicht") || f.includes("flow")
    );
    for (const f of flowFiles) {
      const ref = `file:${f}`;
      if (signalExists(ledger, "code_observation", ref)) continue;

      signals.push(addSignal(ledger, {
        source: "code_observation",
        summary: `Flow-Datei geändert: ${f}`,
        evidenceRefs: [ref],
      }));
    }

    // Skill changes
    const skillFiles = files.filter((f) =>
      f.includes("skill") && !f.includes("node_modules")
    );
    for (const f of skillFiles) {
      const ref = `file:${f}`;
      if (signalExists(ledger, "code_observation", ref)) continue;

      signals.push(addSignal(ledger, {
        source: "code_observation",
        summary: `Skill-Datei geändert: ${f}`,
        evidenceRefs: [ref],
      }));
    }
  } catch {
    // git not available
  }

  return signals;
}

import { randomUUID } from "crypto";
import type {
  Ledger,
  RawSignal,
  Candidate,
  CandidateType,
  ArtifactRef,
} from "./ledger.js";

// ============================================================================
// Classify RawSignals into Candidates
// ============================================================================

/**
 * Takes all unclassified (status: "new") signals from the ledger,
 * creates Candidates, and marks signals as "classified".
 * Returns the newly created Candidates.
 */
export function classifyCandidates(ledger: Ledger): Candidate[] {
  const newSignals = ledger.rawSignals.filter((s) => s.status === "new");
  const candidates: Candidate[] = [];

  for (const signal of newSignals) {
    const candidateType = inferCandidateType(signal);
    const artifactRefs = extractArtifactRefs(signal);

    // Check for existing candidate with same artifact ref — merge signals
    const existing = candidateType && artifactRefs.length > 0
      ? candidates.find(
          (c) => c.candidateType === candidateType &&
                 c.artifactRefs?.some((r) => artifactRefs.some((a) => a.id === r.id))
        )
      : null;

    if (existing) {
      // Merge: add signal to existing candidate
      existing.signalIds.push(signal.id);
      if (!existing.summary.includes(signal.summary)) {
        existing.summary += ` + ${signal.summary}`;
      }
    } else {
      const candidate: Candidate = {
        id: randomUUID(),
        signalIds: [signal.id],
        candidateType: candidateType ?? "episodic",
        summary: signal.summary,
        artifactRefs: artifactRefs.length > 0 ? artifactRefs : undefined,
        phase: "classified",
        action: "unresolved",
      };
      candidates.push(candidate);
      ledger.syncRunState.candidateIds.push(candidate.id);
    }

    // Mark signal as classified
    signal.status = "classified";
  }

  ledger.candidates.push(...candidates);
  return candidates;
}

// ============================================================================
// Normalize Candidates — enrich references, merge duplicates
// ============================================================================

/**
 * Normalizes candidates: enriches artifact references,
 * detects duplicates from different sources, advances phase.
 */
export function normalizeCandidates(ledger: Ledger): void {
  const unprocessed = ledger.candidates.filter((c) => c.phase === "classified");

  for (const candidate of unprocessed) {
    // Merge duplicates: if two candidates reference the same artifact with the same type
    const duplicate = ledger.candidates.find(
      (other) =>
        other.id !== candidate.id &&
        other.phase === "normalized" &&
        other.candidateType === candidate.candidateType &&
        other.artifactRefs?.some((r) =>
          candidate.artifactRefs?.some((cr) => cr.id === r.id && cr.type === r.type)
        )
    );

    if (duplicate) {
      // Merge into existing normalized candidate
      duplicate.signalIds.push(...candidate.signalIds);
      // Remove the duplicate from the ledger
      const idx = ledger.candidates.indexOf(candidate);
      if (idx >= 0) ledger.candidates.splice(idx, 1);
      continue;
    }

    candidate.phase = "normalized";
  }
}

// ============================================================================
// Type inference from signal content
// ============================================================================

const TYPE_PATTERNS: [RegExp, CandidateType][] = [
  // German patterns (primary)
  [/entscheidung|decision|beschluss/i, "decision"],
  [/präferenz|wunsch|vorliebe|bevorzug/i, "preference"],
  [/constraint|einschränkung|beschränkung/i, "constraint"],
  [/trade-off|abwägung|spannungsfeld/i, "tradeoff"],
  [/annahme|assumption|hypothese/i, "assumption"],
  [/befund|gap|widerspruch|problem|lücke/i, "finding"],
  [/aufgabe(?! ohne)|task(?! ohne)/i, "task"],
  [/meilenstein|milestone/i, "milestone_candidate"],
  [/flow|ablauf|userflow|absicht/i, "flow_change"],
  [/feature|fähigkeit/i, "feature_change"],
  [/semantisch|konsolidier/i, "recommend_semantic"],
  [/prozedural|workflow|pattern/i, "recommend_procedural"],

  // Artifact observation patterns
  [/neue entscheidung:|geänderte entscheidung:/i, "decision"],
  [/aktive präferenz:/i, "preference"],
  [/entwicklungsaufgabe ohne feature/i, "task"],
  [/meilenstein ohne feature/i, "milestone_candidate"],
  [/modell-.*datei geändert|policy-.*datei geändert/i, "episodic"],
  [/skill-datei geändert/i, "episodic"],
  [/flow-datei geändert/i, "flow_change"],
];

function inferCandidateType(signal: RawSignal): CandidateType | null {
  for (const [pattern, type] of TYPE_PATTERNS) {
    if (pattern.test(signal.summary)) return type;
  }
  return null;
}

// ============================================================================
// Extract artifact refs from signal evidence
// ============================================================================

function extractArtifactRefs(signal: RawSignal): ArtifactRef[] {
  const refs: ArtifactRef[] = [];
  if (!signal.evidenceRefs) return refs;

  for (const ref of signal.evidenceRefs) {
    // Format: "decision:uuid", "task:uuid", "preference:uuid", etc.
    const match = ref.match(/^(\w+):(.+)$/);
    if (match) {
      const [, type, id] = match;
      if (type !== "file") { // file refs are not artifact refs
        refs.push({ type, id });
      }
    }
  }

  return refs;
}

import type {
  Ledger,
  Candidate,
  ObligationEntry,
  ObligationPriority,
  ArtifactRef,
} from "./ledger.js";
import type { SyncContext } from "./sync-context.js";

// ============================================================================
// Obligation draft type (before merge with previous ledger)
// ============================================================================

export type ObligationDraft = Omit<
  ObligationEntry,
  "status" | "detectedAt" | "resolvedAt" | "deferralReason" | "deferReviewAt"
>;

// ============================================================================
// Derive obligations from candidates + SyncContext enrichment
// ============================================================================

/**
 * Derives obligations from normalized candidates in the ledger.
 * Uses pre-fetched SyncContext for enrichment data.
 */
export function deriveObligationsFromCandidates(
  ledger: Ledger,
  ctx: SyncContext,
  since: Date
): ObligationDraft[] {
  const obligations: ObligationDraft[] = [];

  const allFeatures = ctx.features;

  // Build lookup maps
  const decisionById = new Map(ctx.decisions.map((d: any) => [d.id, d]));
  const taskById = new Map(ctx.tasks.map((t: any) => [t.id, t]));
  const milestoneById = new Map(ctx.milestones.map((m: any) => [m.id, m]));

  // Collect P-MS01 hits for aggregation
  const ms01Hits: { milestone: any; signalRefs: string[]; ref: ArtifactRef }[] = [];

  // Process each candidate
  for (const candidate of ledger.candidates) {
    if (candidate.action === "discard") continue;

    const signalRefs = candidate.signalIds;

    // --- Decision candidates ---
    if (candidate.candidateType === "decision") {
      const decisionRef = candidate.artifactRefs?.find((r) => r.type === "decision");
      const decision = decisionRef ? decisionById.get(decisionRef.id) : null;

      if (decision) {
        const durability = decision.durability;
        const plannedSuccessor = decision.plannedSuccessor ?? decision.planned_successor;
        const reviewCondition = decision.reviewCondition ?? decision.review_condition;
        const tradeOffId = decision.tradeOffId ?? decision.trade_off_id;
        const modelRefs = decision.modelRefs ?? decision.model_refs ?? [];

        // P-E01: Decision ohne Durability (critical)
        if (!durability) {
          obligations.push(makeObligation({
            rule: "P-E01",
            artifactId: decision.id,
            artifactTitle: decision.title,
            signalType: "decision",
            priority: "critical",
            description: `Entscheidung ohne Dauerhaftigkeit: „${decision.title}"`,
            reason: "Jede Entscheidung muss ihre Dauerhaftigkeit (permanent/temporary/transitional) benennen.",
            sourceSignalRefs: signalRefs,
            relatedArtifactRefs: [{ type: "decision", id: decision.id }],
          }));
        }

        // P-E02: Temp/transitional ohne Nachfolger/Review (important)
        if (
          (durability === "temporary" || durability === "transitional") &&
          !plannedSuccessor && !reviewCondition
        ) {
          obligations.push(makeObligation({
            rule: "P-E02",
            artifactId: decision.id,
            artifactTitle: decision.title,
            signalType: "decision",
            priority: "important",
            description: `Temporäre Entscheidung ohne Nachfolger oder Review: „${decision.title}"`,
            reason: "Temporäre/transitionale Entscheidungen brauchen geplanten Nachfolger oder Review-Bedingung.",
            sourceSignalRefs: signalRefs,
            relatedArtifactRefs: [{ type: "decision", id: decision.id }],
          }));
        }

        // P-E03: Decision ohne Trade-off (recommended) — nur neue
        const created = decision.createdAt ?? decision.created_at;
        const isNew = created && new Date(created) > since;
        if (isNew && !tradeOffId) {
          obligations.push(makeObligation({
            rule: "P-E03",
            artifactId: decision.id,
            artifactTitle: decision.title,
            signalType: "decision",
            priority: "recommended",
            description: `Neue Entscheidung ohne Trade-off-Verknüpfung: „${decision.title}"`,
            reason: "Decisions sollten auf den Trade-off verweisen, den sie auflösen.",
            sourceSignalRefs: signalRefs,
            relatedArtifactRefs: [{ type: "decision", id: decision.id }],
          }));
        }

        // P-M01: Decision ohne Modell-Referenz (recommended) — nur wenn Durability gesetzt
        if (isNew && durability && (modelRefs.length === 0)) {
          obligations.push(makeObligation({
            rule: "P-M01",
            artifactId: decision.id,
            artifactTitle: decision.title,
            signalType: "decision",
            priority: "recommended",
            description: `Neue Entscheidung ohne Modell-Referenz: „${decision.title}"`,
            reason: "Decisions sollten auf relevante Modell-Abschnitte verweisen.",
            sourceSignalRefs: signalRefs,
            relatedArtifactRefs: [{ type: "decision", id: decision.id }],
          }));
        }
      }
    }

    // --- Preference candidates ---
    if (candidate.candidateType === "preference") {
      const prefRef = candidate.artifactRefs?.find((r) => r.type === "preference");
      if (prefRef) {
        obligations.push(makeObligation({
          rule: "P-P01",
          artifactId: prefRef.id,
          artifactTitle: candidate.summary,
          signalType: "preference",
          priority: "important",
          description: `Aktive Präferenz noch nicht klassifiziert: ${candidate.summary}`,
          reason: "Aktive Präferenzen müssen weiter klassifiziert (→ Constraint, Trade-off) oder verworfen werden.",
          sourceSignalRefs: signalRefs,
          relatedArtifactRefs: [prefRef],
        }));
      }
    }

    // --- Task candidates (P-T01: critical) ---
    if (candidate.candidateType === "task") {
      const taskRef = candidate.artifactRefs?.find((r) => r.type === "task");
      const task = taskRef ? taskById.get(taskRef.id) : null;
      if (task && !(task.featureId ?? task.feature_id)) {
        obligations.push(makeObligation({
          rule: "P-T01",
          artifactId: task.id,
          artifactTitle: task.title,
          signalType: "task",
          priority: "critical",
          description: `Entwicklungsaufgabe ohne Feature-Referenz: „${task.title}"`,
          reason: "Featurebasierte Arbeit muss auf das Feature referenzieren, sonst geht die Zuordnung verloren.",
          sourceSignalRefs: signalRefs,
          relatedArtifactRefs: [{ type: "task", id: task.id }],
        }));
      }
    }

    // --- Milestone candidates (P-MS01: important) ---
    // Collected per-candidate, aggregated after the loop (see below)
    if (candidate.candidateType === "milestone_candidate") {
      const msRef = candidate.artifactRefs?.find((r) => r.type === "milestone");
      const milestone = msRef ? milestoneById.get(msRef.id) : null;
      if (milestone) {
        const linkedFeatures = milestone.milestoneFeatures ?? milestone.milestone_features ?? [];
        if (linkedFeatures.length === 0 && milestone.status !== "completed" && milestone.status !== "cancelled") {
          ms01Hits.push({ milestone, signalRefs, ref: { type: "milestone", id: milestone.id } });
        }
      }
    }

    // --- Finding candidates (P-B01: critical) ---
    if (candidate.candidateType === "finding") {
      // A finding signal was raised but may not be persisted yet
      obligations.push(makeObligation({
        rule: "P-B01",
        artifactId: candidate.artifactRefs?.[0]?.id,
        artifactTitle: candidate.summary,
        signalType: "finding",
        priority: "critical",
        description: `Konzeptrelevanter Befund erkannt: ${candidate.summary}`,
        reason: "Zentrale konzeptrelevante Befunde müssen als Issue/Befund gesichert werden.",
        sourceSignalRefs: signalRefs,
        relatedArtifactRefs: candidate.artifactRefs ?? [],
      }));
    }

    // --- Recommend semantic/procedural (P-G02: recommended) ---
    if (candidate.candidateType === "recommend_semantic" || candidate.candidateType === "recommend_procedural") {
      const memType = candidate.candidateType === "recommend_semantic" ? "semantisches" : "prozedurales";
      obligations.push(makeObligation({
        rule: "P-G02",
        artifactId: candidate.id,
        artifactTitle: candidate.summary,
        signalType: "memory",
        priority: "recommended",
        description: `Empfehlung für ${memType} Gedächtnis: ${candidate.summary}`,
        reason: `Sync empfiehlt ${memType} Gedächtnis, schreibt es aber nicht automatisch.`,
        sourceSignalRefs: signalRefs,
        relatedArtifactRefs: [],
      }));
    }
  }

  // --- P-MS01: aggregate milestone obligations ---
  const MS01_AGGREGATE_THRESHOLD = 3;
  if (ms01Hits.length > MS01_AGGREGATE_THRESHOLD) {
    // Systemic gap — aggregate into single obligation
    const allSignalRefs = ms01Hits.flatMap((h) => h.signalRefs);
    const allArtifactRefs = ms01Hits.map((h) => h.ref);
    const names = ms01Hits.map((h) => h.milestone.name).slice(0, 3).join(", ");
    obligations.push(makeObligation({
      rule: "P-MS01",
      artifactId: "aggregate",
      artifactTitle: `${ms01Hits.length} Meilensteine`,
      signalType: "milestone",
      priority: "important",
      description: `${ms01Hits.length} Meilensteine ohne Feature-Bündelung (${names}, …)`,
      reason: "Mehrere Milestones ohne Feature-Bündelung — möglicherweise noch nicht gepflegt.",
      sourceSignalRefs: allSignalRefs,
      relatedArtifactRefs: allArtifactRefs,
    }));
  } else {
    // Few enough to be individually actionable
    for (const hit of ms01Hits) {
      obligations.push(makeObligation({
        rule: "P-MS01",
        artifactId: hit.milestone.id,
        artifactTitle: hit.milestone.name,
        signalType: "milestone",
        priority: "important",
        description: `Meilenstein ohne Feature-Bündelung: „${hit.milestone.name}"`,
        reason: "Meilensteine sollen Features bündeln, nicht Aufgaben.",
        sourceSignalRefs: hit.signalRefs,
        relatedArtifactRefs: [hit.ref],
      }));
    }
  }

  // --- P-F01: flow nodes without explicit actor (important) ---
  // Global check against all flow nodes, not candidate-based.
  // Only flag nodes created after the actor field was available (migration 0026).
  const flowNodesWithoutActor = ctx.flows.filter((n: any) => !n.actor || n.actor === "user");
  const flowNodesWithActor = ctx.flows.filter((n: any) => n.actor && n.actor !== "user");
  // Only activate if at least some nodes have been explicitly set — otherwise it's pre-migration default
  if (ctx.flows.length > 0 && flowNodesWithActor.length > 0 && flowNodesWithoutActor.length > 0) {
    const F01_AGGREGATE_THRESHOLD = 3;
    if (flowNodesWithoutActor.length > F01_AGGREGATE_THRESHOLD) {
      obligations.push(makeObligation({
        rule: "P-F01",
        artifactId: "aggregate",
        artifactTitle: `${flowNodesWithoutActor.length} Flow-Knoten`,
        signalType: "flow",
        priority: "important",
        description: `${flowNodesWithoutActor.length} Flow-Knoten ohne expliziten Akteur`,
        reason: "Jeder Flow-Schritt muss seinen Akteur (user/agent/system) explizit benennen (P-F01).",
        sourceSignalRefs: [],
        relatedArtifactRefs: flowNodesWithoutActor.map((n: any) => ({ type: "flow_node", id: n.id })),
      }));
    } else {
      for (const n of flowNodesWithoutActor) {
        obligations.push(makeObligation({
          rule: "P-F01",
          artifactId: n.id,
          artifactTitle: n.name,
          signalType: "flow",
          priority: "important",
          description: `Flow-Knoten ohne expliziten Akteur: „${n.name}"`,
          reason: "Jeder Flow-Schritt muss seinen Akteur (user/agent/system) explizit benennen.",
          sourceSignalRefs: [],
          relatedArtifactRefs: [{ type: "flow_node", id: n.id }],
        }));
      }
    }
  }

  // --- P-G01: check if episodic memory entry exists (critical) ---
  // This is a global check, not candidate-specific
  const entriesSince = ctx.memories.filter((e: any) => {
    const t = e.createdAt ?? e.created_at;
    return t && new Date(t) > since;
  });
  if (entriesSince.length === 0) {
    obligations.push(makeObligation({
      rule: "P-G01",
      signalType: "memory",
      priority: "critical",
      description: "Kein episodischer Gedächtniseintrag seit letztem Commit",
      reason: "Zentrale Session-Erkenntnisse müssen als episodisches Gedächtnis gesichert werden.",
      sourceSignalRefs: [],
      relatedArtifactRefs: [],
    }));
  }

  return obligations;
}

// ============================================================================
// Helper: create obligation draft
// ============================================================================

function makeObligation(opts: {
  rule: string;
  artifactId?: string;
  artifactTitle?: string;
  signalType: string;
  priority: ObligationPriority;
  description: string;
  reason?: string;
  sourceSignalRefs: string[];
  relatedArtifactRefs: ArtifactRef[];
}): ObligationDraft {
  return {
    id: `${opts.rule}::${opts.artifactId ?? "global"}`,
    signalType: opts.signalType,
    artifactId: opts.artifactId,
    artifactTitle: opts.artifactTitle,
    priority: opts.priority,
    description: opts.description,
    rule: opts.rule,
    reason: opts.reason,
    sourceSignalRefs: opts.sourceSignalRefs,
    relatedArtifactRefs: opts.relatedArtifactRefs,
  };
}

// ============================================================================
// Group obligations by priority for display
// ============================================================================

export function groupByPriority(obligations: ObligationEntry[]): {
  critical: ObligationEntry[];
  important: ObligationEntry[];
  recommended: ObligationEntry[];
} {
  return {
    critical: obligations.filter((o) => o.priority === "critical"),
    important: obligations.filter((o) => o.priority === "important"),
    recommended: obligations.filter((o) => o.priority === "recommended"),
  };
}

// ============================================================================
// Summarize for display
// ============================================================================

export function obligationSummary(obligations: ObligationEntry[]): {
  totalOpen: number;
  criticalOpen: number;
  importantOpen: number;
  importantDeferred: number;
  recommendedOpen: number;
} {
  const open = obligations.filter((o) => o.status === "open");
  const deferred = obligations.filter((o) => o.status === "deferred");
  return {
    totalOpen: open.length,
    criticalOpen: open.filter((o) => o.priority === "critical").length,
    importantOpen: open.filter((o) => o.priority === "important").length,
    importantDeferred: deferred.filter((o) => o.priority === "important").length,
    recommendedOpen: open.filter((o) => o.priority === "recommended").length,
  };
}

