// ============================================================================
// Rotate: keep last N signals, discard rest (controlled context size)
// ===========================================================================

export interface RotateOpts {
  commitHash?: string;
  branch?: string;
  topic?: string;
  /** Max raw signals to keep (default 50) */
  maxSignals?: number;
}

export function rotateLedger(prev: Ledger, opts: RotateOpts): Ledger {
  const maxSignals = opts.maxSignals ?? 50;
  const now = new Date().toISOString();

  // Keep only the most recent N signals
  const sortedSignals = [...prev.rawSignals]
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
    .slice(0, maxSignals);

  // Retain candidates linked to surviving signals
  const signalIds = new Set(sortedSignals.map((s) => s.id));
  const retainedCandidates = prev.candidates.filter(
    (c) => c.signalIds.some((id) => signalIds.has(id))
  );

  // Retain transition notes linked to surviving candidates/obligations
  const candidateIds = new Set(retainedCandidates.map((c) => c.id));
  const retainedNotes = prev.transitionNotes.filter(
    (n) =>
      (n.relatedCandidateId && candidateIds.has(n.relatedCandidateId)) ||
      (n.relatedObligationId && prev.obligations.some((o) => o.id === n.relatedObligationId))
  );

  return {
    ...prev,
    version: 2,
    sessionMeta: {
      ...prev.sessionMeta,
      updatedAt: now,
      topic: opts.topic ?? prev.sessionMeta.topic,
    },
    rawSignals: sortedSignals,
    candidates: retainedCandidates,
    // Obligations are cleared — they are re-derived each sync via mergeWithPreviousLedger
    obligations: [],
    transitionNotes: retainedNotes,
    syncRunState: {
      currentPhase: "raw",
      rawSignalIds: sortedSignals.map((s) => s.id),
      candidateIds: retainedCandidates.map((c) => c.id),
      obligationIds: [],
      syncStatus: "draft",
    },
    completionStatus: prev.completionStatus,
    commitHash: opts.commitHash ?? prev.commitHash,
    branch: opts.branch ?? prev.branch,
    updatedAt: now,
  };
}

